/** Drag handle. The Geist set has no grip, so this is MoreVerticalIcon's own geometry mirrored
 *  into two columns — same 1.5 radius, same three rows — which is why it sits alongside the
 *  other icons without looking imported. */
export function GripIcon({
  className,
  ...props
}: { className?: string } & React.SVGProps<SVGSVGElement>) {
  return (
    <svg
      viewBox="0 0 16 16"
      width="16"
      height="16"
      fill="none"
      className={className}
      aria-hidden="true"
      {...props}
    >
      {[5, 11].map((cx) =>
        [2.5, 8, 13.5].map((cy) => (
          <circle
            key={`${cx}-${cy}`}
            cx={cx}
            cy={cy}
            r="1.5"
            fill="currentColor"
          />
        )),
      )}
    </svg>
  );
}
